import{_ as a,o as e,c as l,ag as s}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"SetColliEnable 开启关闭碰撞检测","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetColliEnable.md","filePath":"3. 指令/5. 设置指令/SetColliEnable.md","lastUpdated":1778862643000}'),i={name:"3. 指令/5. 设置指令/SetColliEnable.md"};function n(r,t,o,d,h,p){return e(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="setcollienable-开启关闭碰撞检测" tabindex="-1">SetColliEnable 开启关闭碰撞检测 <a class="header-anchor" href="#setcollienable-开启关闭碰撞检测" aria-label="Permalink to &quot;SetColliEnable 开启关闭碰撞检测&quot;">​</a></h1><p>该指令用于<strong>开启或关闭机器人轴的具体碰撞检测功能</strong>。通过该指令，可以灵活地为单个轴或整个轴组配置安全防护逻辑。当检测到电机的反馈力矩超过预设的安全阈值时，机器人会立即停止运动，从而保护硬件、工装及周围人员。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetColliEnable(AxisID, Valid) SetColliEnable(轴号, 有效性)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>AxisID：轴号</td><td>enum（枚举型）</td><td>指定需要设置碰撞检测的对象。<br>* <strong>GROUP</strong>：全部关节轴（通常为 1-6 轴）。<br>* <strong>A1 - A6</strong>：分别对应机器人的第 1 轴至第 6 轴。</td><td></td></tr><tr><td>Valid：有效性</td><td>enum（枚举型）</td><td>* <strong>ENABLE</strong>：开启碰撞检测功能。<br>* <strong>DISABLE</strong>：关闭碰撞检测功能。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>碰撞检测基于机器人的动力学模型。系统会实时对比&quot;计算力矩&quot;与&quot;实际反馈力矩&quot;。当两者之差超过允许范围时，系统判定发生碰撞。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetColliEnable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GROUP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ENABLE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>执行结果：</strong></p><p>全轴开启碰撞检测。在后续运动中，任何一个关节受到异常外力冲击，机器人都会自动触发停机保护。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>柔性装配</strong>：在精密对接或插入作业中开启此功能，防止因配合偏差导致的机械损伤。</li><li><strong>人机协作环境</strong>：在人员可能进入的工作区域边缘开启全轴检测，提高安全系数。</li><li><strong>特殊工艺屏蔽</strong>：在执行某些由于工艺特性会产生较大反作用力（如重力冲压或接触式打磨）的任务时，可能需要临时对特定轴执行 <code>DISABLE</code> 以避免误报警。</li></ul>',18)])])}const u=a(i,[["render",n]]);export{c as __pageData,u as default};
